notes.schema:
CREATE TABLE `filiere` (
  `id_filiere` INTEGER PRIMARY KEY,
  `nom_filiere` VARCHAR(50)
);
CREATE TABLE `promotion` (
  `id_promo` INTEGER PRIMARY KEY,
  `nom_promo` VARCHAR(25),
  `ref_univers` INTEGER,
  FOREIGN KEY (`ref_univers`) REFERENCES `filiere`(`id_filiere`)
);
CREATE TABLE `etudiant` (
  `id_et` INTEGER PRIMARY KEY,
  `nom_et` VARCHAR(50),
  `prenom_et` VARCHAR(50),
  `date_Naissance_et` TIMESTAMP,
  `ref_promo` INTEGER,
  FOREIGN KEY (`ref_promo`) REFERENCES `promotion`(`id_promo`)
);
CREATE TABLE `notes` (
  `ref_module` INTEGER,
  `ref_etudiant` INTEGER,
  `note` FLOAT,
  PRIMARY KEY (`ref_module`, `ref_etudiant`),
  FOREIGN KEY (`ref_etudiant`) REFERENCES `etudiant`(`id_et`),
  FOREIGN KEY (`ref_module`) REFERENCES `module`(`id_module`)
);
CREATE TABLE `module` (
  `id_module` INTEGER PRIMARY KEY,
  `nom_module` VARCHAR(50)
);
CREATE TABLE `uniteEnseignement` (
  `id_UE` INTEGER PRIMARY KEY,
  `nom_UE` VARCHAR(100),
  `nombre_credit` INTEGER,
  `ref_promo` INTEGER,
  `numeroAnnee` INTEGER,
  FOREIGN KEY (`ref_promo`) REFERENCES `promotion`(`id_promo`)
);
CREATE TABLE `compositionUE` (
  `ref_UE` INTEGER,
  `ref_module` INTEGER,
  `coef` INTEGER,
  PRIMARY KEY (`ref_UE`, `ref_module`),
  FOREIGN KEY (`ref_UE`) REFERENCES `uniteEnseignement`(`id_UE`),
  FOREIGN KEY (`ref_module`) REFERENCES `module`(`id_module`)
);
CREATE TABLE `anneeEtude` (
  `ref_promo` INTEGER,
  `numeroAnnee` INTEGER,
  PRIMARY KEY (`ref_promo`, `numeroAnnee`),
  FOREIGN KEY (`ref_promo`) REFERENCES `promotion`(`id_promo`)
);
CREATE TABLE `UEvalidee` (
  `ref_etudiant` INTEGER,
  `ref_UE` INTEGER,
  PRIMARY KEY (`ref_etudiant`, `ref_UE`),
  FOREIGN KEY (`ref_etudiant`) REFERENCES `etudiant`(`id_et`),
  FOREIGN KEY (`ref_UE`) REFERENCES `uniteEnseignement`(`id_UE`)
);

